We start by proving the following 2 auxiliary statements:

\begin{lemma}\label{l:rep}
  Let the Frobenius normal form $U\cdot C\cdot U^{-1}$ of $A$ be given.
  Using
  $\Ot(n^2)$
  field operations we can compute an \emph{auxiliary matrix}
  $(r_{i,j})=R\in \field^{n\times (2n-1)}$, such that for any $k\in[n]$:
  \begin{equation*}
    U\cdot C^k=\begin{bmatrix}
      r_{1,k} & r_{1,k+1} & \dots & r_{1,n+k-1}\\
      r_{2,k} & r_{2,k+1} & \dots & r_{2,n+k-1}\\
      \vdots & \vdots & \ddots & \vdots\\
      r_{n,k} & r_{n,k+1} & \dots & r_{n,n+k-1}
    \end{bmatrix}:=R_k.
  \end{equation*}
\end{lemma}
\begin{proof}
  Let $u_i=(u_{i,1},\ldots, u_{i,n})$ be the $i$-th row of the matrix $U$.
  For any $k>n$ define $u_{i,k}$ inductively:
  \begin{equation*}
    u_{i,k}=-c_0\cdot u_{i,k-n}-c_1\cdot u_{i,k-n+1}-\ldots-c_{n-1}\cdot u_{i,k-1}=-\sum_{i=0}^{n-1}c_i\cdot u_{i,k-n+i}.
  \end{equation*}
  In other words, $(u_i)_{i=1}^\infty$ is a linearly recursive sequence of order $n$.
  As discussed in the proof of Lemma~\ref{l:keller}, for any $k\geq 0$, we have:
  \begin{equation*}
    u_i\cdot C^k=(u_{i,1+k},\ldots,u_{i,n+k}).
  \end{equation*}
  In particular, for $k=n-1$, we obtain:
  \begin{equation*}
    u_i\cdot C^{n}=(u_{i,n+1},\ldots,u_{i,2n})=(r_{i,n},\ldots,r_{i,2n-1}).
  \end{equation*}
  Since $(r_{i,1},\ldots,r_{i,n-1})=(u_{i,2},\ldots,u_{n})$, the $i$-th row of the
  matrix $R$ can be obtained by computing the terms $n+1,\ldots,2n$ of
  the linearly recursive sequence $(u_i)_{i=1}^\infty$.
  As shown in~\cite[Theorem~3]{BostanM21}, this can be done using $\Ot(n)$ field operations.
  Therefore, by applying this to all $i$, computing the entire matrix $R$
  is possible using $\Ot(n^2)$ field operations.
\end{proof}

\begin{theorem}\label{t:powers}
  Let $A\in \field^{n\times n}$ be generic and let $U\cdot C\cdot U^{-1}$ be its Frobenius form.
  Let $R=(r_{i,j})$ be the associated auxiliary matrix of Lemma~\ref{l:rep}.
  Let $S,T\subseteq [n]$.
  Let $h=\lfloor n^{\alpha}\rfloor$, $|S|=\lfloor n^{s}\rfloor$, ${|T|=\lfloor n^t\rfloor}$ for some $\alpha,s,t\in [0,1]$.
  Then, the submatrices $(A^1)_{S,T},\ldots,(A^h)_{S,T}$ can be computed
  using $\Ot(n^{\omega(s,1-\alpha,t)+\alpha})$ field operations.
\end{theorem}
\begin{proof}
  Set $\Delta=\lceil n/h\rceil$.
  Put $U^{-1}=(g_{i,j})$. For all $i\in S$ and $j\in \{0,\ldots,\Delta-1\}$, let
  \begin{equation*}
    p_{i,j}(x)=r_{i,j\cdot h+1}\cdot x+r_{i,j\cdot h+2}\cdot x^2+\ldots +r_{i,j\cdot h+(2h-1)}\cdot x^{2h-1}
  \end{equation*}
  be a polynomial. Similarly, for all $i\in T$ and $j\in\{0,\ldots,\Delta-1\}$, let us introduce a polynomial
  \begin{equation*}
    q_{j,i}(x)=g_{j\cdot h+1,i}\cdot x^{h-1}+g_{j\cdot h+2,i}\cdot x^{h-2}+\ldots + g_{j\cdot h+h,i}\cdot x^0.
  \end{equation*}
  In the above, every value $r_{\cdot,\cdot}$ and $g_{\cdot,\cdot}$ that has not been defined
  is assumed to be equal to $0$.

  Each $p_{i,j}$ is a polynomial of degree $2h-1$, and each $q_{j,i}$ is a polynomial of degree $h-1$.
  Consider the polynomial matrices $P=(p_{i,j})\in \field[x]^{|S|\times \Delta}$ and $Q=(q_{j,i})\in \field[x]^{\Delta\times |T|}$.
  The product $P\cdot Q$ can be computed in $\Ot(n^{\omega(s,1-\alpha,t)}\cdot h)=\Ot(n^{\omega(s,1-\alpha,t)+\alpha})$
  time since arithmetic operations on polynomials of degree at most $h$ can be carried out
  in $\Ot(h)$ time~\cite{fft}.

  Now, for $i\in S$, $j\in T$, and $k\in \{h,\ldots,2h-1\}$ consider the coefficient $d_{i,j,k}$
  of $x^k$ in the polynomial $(P\cdot Q)_{i,j}$
  of degree at most $3h$. We have:
  \begin{equation*}
    d_{i,j,k}=\sum_{t=0}^{\Delta-1} \sum_{l=1}^{h} r_{i,t\cdot h+(k-h)+l}\cdot g_{t\cdot h+l,j}.
  \end{equation*}
  Now consider the element $A_{i,j}^k$, for $k\in[h]$:
  \begin{align*}
    A_{i,j}^k&=(UC^kU^{-1})_{i,j}=\sum_{z=1}^n (UC^k)_{i,z}\cdot g_{z,j}\\
    &=\sum_{z=1}^n r_{i,z+k-1}\cdot g_{z,j}=\sum_{t=0}^{\Delta-1}\sum_{l=1}^h r_{i,t\cdot h+(k-1)+l}\cdot g_{t\cdot h+l,j}=d_{i,j,k+h-1}.
  \end{align*}
  We conclude that all the required entries in the respective submatrices $S\times T$ of $A^1,\ldots,A^h$ are encoded as coefficients
  of the (polynomial) entries of the matrix $P\cdot Q$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
  Fix the field $\field$ to be $\mathbb{Z}/p\mathbb{Z}$ for some prime number
    $p=\Theta(n^{4+c})$, where $c\geq 1$ is a constant controlling the error probability.
    Let $A\in \field^{n\times n}$ be a weighted adjacency matrix of Theorem~\ref{t:graph-matrix}.
    Recall that $A$ is generic with probability at least $1-1/n^c$.
  The preprocessing is simply to compute the matrix powers $A^1,\ldots,A^{h}$,
    which can be done in $\Ot(n^{\omega(1,1-\alpha,1)+\alpha})$ time by Theorem~\ref{t:powers}.
    Theorem~\ref{t:powers} requires an FNF of $A$, which can be computed in $\Ot(n^\omega)$ time by Lemma~\ref{l:fnf-simple},
    and an auxiliary matrix $R$ of Lemma~\ref{l:rep}, computed in $\Ot(n^2)$ time.
    Note that $\omega(1,1-\alpha,1)+\alpha\geq\omega$.

  Observe that if the graph $G$ is subject to a failure of a single edge $f=uv$, the weighted adjacency matrix $A$ -- assuming the same variable substitution in $\asym(G)$ -- undergoes
  a single \emph{element update} of changing the entry $A_{u,v}$, $u\neq v$, to $0$.
    Let $B$ denote the matrix $A$ after such an update.
    By Lemma~\ref{l:matrix-inverse}, for any $s,t\in V$, we can
    compute $(B^1)_{s,t},\ldots,(B^{h})_{s,t}$ in $\Ot(h)$ time.
    By Theorem~\ref{t:graph-matrix}, with high probability, if $d\leq h$ is minimal such that $(B^d)_{s,t}\neq 0$, then
    $\dist_{G-f}(s,t)=d$, and otherwise, if such a value $d$ does not exists then $\dist_{G-f}(s,t)>h$
    and thus $\min(\dist_{G-F}(s,t),h)=h$.
  \end{proof}
